def transform(grid):
    n = len(grid)
    block = 3
    out = []
    for r in range(0, n, block):
        row = []
        for c in range(0, len(grid[0]), block):
            counts = {}
            for i in range(r, min(r + block, n)):
                for j in range(c, min(c + block, len(grid[0]))):
                    v = grid[i][j]
                    if v not in (0, 5):
                        counts[v] = counts.get(v, 0) + 1
            row.append(max(counts, key=counts.get) if counts else 0)
        out.append(row)
    return out
